/**
 * Every tag, for the hero's tag picker: primary tags in their order, each
 * followed by its children, then the secondary tags by name. Any of them can
 * feed the hero (Portal\Hero matches the tag id, whatever its kind).
 *
 * 🚨 Loaded through the tag list once: the admin's store may already hold a
 * few tags (from another page), and "the store is not empty" is not "every
 * tag is loaded".
 */
let tagsRequested = false;
function tagOptions() {
  if (!tagsRequested && has('flarum-tags')) {
    tagsRequested = true;
    const list = app.tagList;
    (list ? list.load(['parent']) : app.store.find('tags', {
      include: 'parent'
    })).then(() => m.redraw());
  }
  const tags = app.store.all('tags');
  const byPosition = (a, b) => a.position() - b.position();
  // A list, not an object: an object's numeric keys (tag ids) iterate in
  // number order, which would undo the order built here.
  const options = [['0', t('hero.tag_none')]];
  const add = (tag, label) => options.push([String(tag.id()), label]);
  tags.filter(tag => tag.position() !== null && !tag.parent()).sort(byPosition).forEach(tag => {
    add(tag, tag.name());
    tags.filter(child => child.parent() === tag).sort(byPosition).forEach(child => add(child, '— ' + child.name()));
  });
  tags.filter(tag => tag.position() === null && !tag.parent()).sort((a, b) => a.name().localeCompare(b.name())).forEach(tag => add(tag, t('hero.tag_secondary', {
    name: tag.name()
  })));

  // A tag that is none of the above (a child whose parent is not loaded)
  // still shows by name rather than going missing.
  tags.filter(tag => !options.some(([id]) => id === String(tag.id()))).forEach(tag => add(tag, tag.name()));
  return options;
}
